import React, { useState } from 'react';
import './Login.css';

export default function Login({onLogin}) { const [role,setRole]=useState('owner'); return <div className="login-page"><div className="login-left"><div className="brand login-brand"><div className="brand-logo">E<span>+</span></div><div className="brand-text"><strong>estateflow<span>.</span></strong><small>CRM PLATFORM</small></div></div><div className="login-hero"><span className="pill light">REAL ESTATE, IN ONE FLOW</span><h1>Every lead has a story.<br/><em>Close the next chapter.</em></h1><p>The modern workspace for property teams — from first enquiry to final booking.</p><div className="hero-points"><span>✓ Smart lead pipeline</span><span>✓ Team performance</span><span>✓ Sales, visits & payroll</span></div></div><div className="login-decoration"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="float-card card-one"><span className="mini-icon purple">↗</span><div><small>Conversion rate</small><b>+24.8%</b></div></div><div className="float-card card-two"><span className="mini-icon green">✓</span><div><small>Site visits today</small><b>12 scheduled</b></div></div></div><div className="login-foot">A flexible CRM workspace for growing real estate teams.</div></div><div className="login-right"><form className="login-box" onSubmit={e=>{e.preventDefault();onLogin(role)}}><span className="eyebrow">WELCOME TO ESTATEFLOW</span><h2>Sign in to your workspace</h2><p>Choose a demo role to explore the product.</p><div className="role-cards"><button type="button" className={role==='owner'?'chosen':''} onClick={()=>setRole('owner')}><span>♙</span><b>Company Owner</b><small>Manage your team</small></button><button type="button" className={role==='employee'?'chosen':''} onClick={()=>setRole('employee')}><span>♧</span><b>Employee</b><small>Your daily workspace</small></button><button type="button" className={role==='superadmin'?'chosen':''} onClick={()=>setRole('superadmin')}><span>✦</span><b>Super Admin</b><small>Manage client companies</small></button></div><label className="login-input-label">Demo email<input readOnly value={role==='superadmin'?'admin@estateflow.demo':role==='owner'?'owner@crm-demo.in':'rohit@demo.in'}/></label><label className="login-input-label">Demo password<input readOnly value={role==='superadmin'?'Admin@123':role==='owner'?'Owner@123':'Employee@123'}/></label><button className="btn primary login-btn">Continue to CRM <span>→</span></button><div className="login-warning"><span>ⓘ</span><p><b>Demo environment</b><br/>Demo role switching is for preview only. Production authentication and server-side access controls are not connected yet.</p></div></form></div></div>; }
